('cmt15ui2i000ndwldzoqbqrv0','Mahmudul Hasan','mahmudul.hasan@example.com','+8801855443322','Work & Family Visa','Thanks for the help with my Portugal D6 visa application, it was approved last week.','contact_page','RESOLVED','2026-08-12 00:49:45.141','2026-08-12 00:49:45.141',0,NULL),
('cmt15ui2u000odwld4bi6t93p','Ruma Akter','ruma.akter@example.com','+8801977889900','Hotel Booking','Booking confirmed for the Bangkok trip, thank you for the quick turnaround.','contact_page','RESOLVED','2026-08-11 00:49:45.141','2026-08-30 02:52:23.036',1,NULL),
('cmt15ui33000pdwldauonsmj3','Zahid Hassan','zahid.hassan@example.com','+8801699887766','Document Legalization','Received my apostilled documents, everything looks correct. Appreciate the help.','contact_page','RESOLVED','2026-08-09 00:49:45.141','2026-08-09 00:49:45.141',0,NULL),
('cmt15ui3k000qdwldieqnqwvb','Taslima Begum','taslima.begum@example.com','+8801544332211','Tourist Visa','Visa approved for our family trip to Thailand, thanks for handling the paperwork.','contact_page','RESOLVED','2026-08-07 00:49:45.141','2026-08-07 00:49:45.141',0,NULL),
