INSERT INTO `Service` VALUES
('cmt11t66z0000g4ld6sumicwz','air-ticketing','Air Ticketing','Air Ticketing','Reliable Flight Booking for Every Journey','Affordable air ticket booking for domestic and international travel with professional assistance. We compare fares across trusted airlines so you get the best price and confirmed itinerary every time.','[\"Domestic & international flights\",\"One-way and round-trip bookings\",\"Group booking solutions\",\"Best fare comparison & instant confirmation\"]','/uploads/services/33d6d557-385b-4758-ab41-a5be7b56181a.jpg',0,1,'2026-08-19 22:56:44.699','2026-08-30 03:26:54.191',NULL,NULL),
('cmt11t6870001g4ld6coksuzi','hotel-reservations','Hotel','Hotel Reservations','Worldwide Hotel Reservations for Every Budget','We secure hotel rooms around the world at competitive rates, from budget stays to premium resorts, with instant confirmation and flexible cancellation options.','[\"Hotels worldwide at competitive rates\",\"All budget categories covered\",\"Instant booking confirmation\",\"Group & corporate rates\"]','/uploads/services/efe6aa55-f0e5-417b-878b-d48c17aa56dc.webp',1,1,'2026-08-19 22:56:44.743','2026-08-30 03:53:48.773',NULL,NULL),
('cmt11t68q0002g4ldbzdvwyoe','tourist-visa','Visa','Tourist Visa','Tourist Visa Processing Done Right','From document checklists to embassy submission, our team handles your tourist visa application end to end so you can focus on planning the trip, not the paperwork.','[\"Document checklist & review\",\"Application form assistance\",\"Appointment scheduling\",\"Processing status updates\"]','/uploads/services/dbdb977d-a3c0-4125-9533-146e8437c2b5.jpg',2,1,'2026-08-19 22:56:44.762','2026-08-30 03:54:00.662',NULL,NULL),
('cmt11t6950003g4ldxro86tj0','visa-stamping','Visa','Visa Stamping','Visa Stamping Support Without the Hassle','We assist with visa stamping for multiple destinations, verifying every document and following up with the embassy until your passport is stamped and ready.','[\"Visa stamping for multiple destinations\",\"Embassy appointment support\",\"Document verification\",\"Follow-up until approval\"]','/uploads/services/9eefb903-485a-47bf-abd1-2e82e26cfcbe.jpg',3,1,'2026-08-19 22:56:44.777','2026-08-30 03:54:16.764',NULL,NULL),
('cmt11t69m0004g4ldsxgblwnh','document-legalization','Legal','Document Legalization','Document Legalization Made Simple','We handle notarization, ministry and embassy legalization of your documents, guiding you through every step so nothing is missing and nothing gets delayed.','[\"Notary & ministry legalization\",\"Embassy attestation\",\"Document translation support\",\"End-to-end handling\"]','/uploads/services/07eb83c7-9f6c-4d9c-9d04-1022da36c64b.jpg',4,1,'2026-08-19 22:56:44.794','2026-08-30 03:54:27.136',NULL,NULL),
('cmt11t6a10005g4ld2dzqkfrk','apostille','Legal','Apostille Services','Fast Apostille for Hague Convention Countries','Get your documents apostilled quickly for use in Hague Convention countries, with embassy legalization and courier delivery handled for you.','[\"Apostille for Hague Convention countries\",\"Embassy legalization for other destinations\",\"Courier & delivery handling\",\"Status tracking\"]','/uploads/services/88ce382e-298d-4e20-9b4d-9e2573c75ff9.jpg',5,1,'2026-08-19 22:56:44.809','2026-08-30 03:25:55.113',NULL,NULL);
COMMIT;
