INSERT INTO `SiteSetting` VALUES
('about_hero','{\"eyebrow\":\"About Us\",\"title\":\"Who We Are\",\"subtitle\":\"A Dhaka-based travel and visa agency helping people fly, study, work and reunite with family abroad — with less paperwork stress.\",\"image\":\"/uploads/about/eef17991-3fd5-42e3-a3ed-d8d7462cc1b3.jpg\",\"titleColor\":\"#f0ac27\",\"shadowColor\":\"#ffffff\"}','2026-08-30 04:09:54.934'),
('blogs_hero','{\"eyebrow\":\"Travel Insights\",\"title\":\"Travel Guide\",\"subtitle\":\"Visa guides, booking tips, and travel know-how from the A&A Aviation team.\",\"image\":\"/uploads/blogs-hero/76d68daf-e82f-4d43-b6ef-458c72c5976c.jpg\",\"titleColor\":\"#f0ac27\",\"shadowColor\":\"#ffffff\"}','2026-08-30 04:11:13.069'),
('contact_form_fields','{\"phoneFieldEnabled\":false}','2026-08-30 04:13:45.514'),
('contact_hero','{\"eyebrow\":\"\",\"title\":\"Contact\",\"subtitle\":\"\",\"image\":\"/uploads/contact-hero/ced82ea3-668d-489c-a058-471ab5950831.jpg\",\"titleColor\":\"#172B47\",\"shadowColor\":\"#ffffff\"}','2026-08-30 04:13:26.866'),
('contact_info','{\"phone\":\"+88 1965 323232\",\"whatsapp\":\"8801965323232\",\"email\":\"info@aaaviation.com\",\"address\":\"Ka 39/1 (3rd Floor), Pragati Sarani, Kuril, Dhaka\",\"latitude\":23.82240147,\"longitude\":90.428699099}','2026-08-30 04:52:23.785'),
('destinations_hero','{\"eyebrow\":\"Global Network\",\"title\":\"Destinations\",\"subtitle\":\"Visa and travel support across the destinations our clients ask for most — pick yours to see what we handle there.\",\"image\":\"/uploads/destinations-hero/79ee7497-36e2-471a-96d0-c49738364ac2.jpg\",\"titleColor\":\"#f0ac27\",\"shadowColor\":\"#ffffff\"}','2026-08-30 04:26:12.473'),
('footer_gallery','[{\"alt\":\"Football fans with Portugal flags\",\"image\":\"/uploads/seed/footer-gallery/gallery-1.png\"},{\"alt\":\"Hillside town view\",\"image\":\"/uploads/seed/footer-gallery/gallery-2.png\"},{\"alt\":\"Colorful boats on a canal\",\"image\":\"/uploads/seed/footer-gallery/gallery-3.png\"},{\"alt\":\"Couple at a terrace cafe\",\"image\":\"/uploads/seed/footer-gallery/gallery-4.png\"},{\"alt\":\"Coastal city and river\",\"image\":\"/uploads/seed/footer-gallery/gallery-5.png\"},{\"alt\":\"Traveler smiling on a mountain overlook\",\"image\":\"/uploads/seed/footer-gallery/hijab-traveler.png\"}]','2026-08-29 08:08:12.802'),
('home_gallery','[{\"alt\":\"Football fans with Portugal flags\",\"image\":\"/uploads/seed/gallery/gallery-1.png\"},{\"alt\":\"Hillside town view\",\"image\":\"/uploads/seed/gallery/gallery-2.png\"},{\"alt\":\"Colorful boats on a canal\",\"image\":\"/uploads/seed/gallery/gallery-3.png\"},{\"alt\":\"Couple at a terrace cafe\",\"image\":\"/uploads/seed/gallery/gallery-4.png\"},{\"alt\":\"Coastal city and river\",\"image\":\"/uploads/seed/gallery/gallery-5.png\"}]','2026-08-29 08:08:12.793'),
