('home_partners','[{\"name\": \"Singapore Airlines\", \"image\": \"/uploads/seed/partners/singapore-airlines.png\"}, {\"name\": \"Marriott\", \"image\": \"/uploads/seed/partners/marriott.png\"}, {\"name\": \"Sheraton\", \"image\": \"/uploads/seed/partners/sheraton.png\"}, {\"name\": \"Accor\", \"image\": \"/uploads/seed/partners/accor.png\"}, {\"name\": \"Holiday Inn\", \"image\": \"/uploads/seed/partners/holiday-inn.png\"}, {\"name\": \"Radisson Hotels & Resorts\", \"image\": \"/uploads/seed/partners/radisson.png\"}, {\"name\": \"Hilton\", \"image\": \"/uploads/seed/partners/hilton.png\"}]','2026-08-29 05:18:25.002'),
('home_people_gallery','[{\"image\":\"/uploads/seed/people-gallery/edge-traveler.png\",\"alt\":\"Traveler reaching up toward the treeline\",\"tall\":false},{\"image\":\"/uploads/seed/people-gallery/hijab-traveler.png\",\"alt\":\"Traveler smiling on a mountain overlook\",\"tall\":true},{\"image\":\"/uploads/seed/people-gallery/backpacker.png\",\"alt\":\"Traveler with a backpack at a busy market\",\"tall\":false},{\"image\":\"/uploads/seed/people-gallery/city-river.png\",\"alt\":\"Riverside city skyline\",\"tall\":true},{\"image\":\"/uploads/seed/people-gallery/edge-canal.png\",\"alt\":\"Canal lined with colorful boats\",\"tall\":false}]','2026-08-29 08:08:12.831'),
('home_service_cards','[{\"category\":\"Hotel\",\"title\":\"Worldwide Hotel Reservations\",\"image\":\"/uploads/service-cards/fe6640c2-06f6-41fc-b3d3-82ccf3583d9a.webp\"},{\"category\":\"Visa\",\"title\":\"Tourist Visa Processing\",\"image\":\"/uploads/service-cards/aeb661fe-5d81-4cff-90f2-de987bfd8df3.jpg\"},{\"category\":\"Visa\",\"title\":\"Visa Stamping Support\",\"image\":\"/uploads/service-cards/72600427-8c57-4a13-89f2-c291cbfd2375.jpg\"},{\"category\":\"Legal\",\"title\":\"Document Legalization\",\"image\":\"/uploads/service-cards/3e2f7b92-c61e-4bba-8a5e-282fcfaecb67.jpg\"},{\"category\":\"Legal\",\"title\":\"Apostille Services\",\"image\":\"/uploads/service-cards/d0c405d6-dfb6-4686-adb4-a7221b6d84ff.jpg\"}]','2026-08-30 04:23:13.485'),
('home_stats','[{\"value\":\"50+\",\"label\":\"Successful Visa Applications\"},{\"value\":\"200+\",\"label\":\"Air Tickets Booked\"},{\"value\":\"20\",\"label\":\"Countries Served\"},{\"value\":\"97%\",\"label\":\"Client Satisfaction\"}]','2026-08-29 07:14:59.740'),
('home_testimonials','[{\"quote\":\"I booked my international flight through A&A Aviation and received excellent support from start to finish. The entire booking process was smooth and hassle-free.\",\"name\":\"Nusrat Jahan\",\"role\":\"Business Owner\",\"caption\":\"great experiences\"},{\"quote\":\"Our family\'s tourist visa was approved without a single hiccup. The team explained every document we needed and kept us updated the whole way through.\",\"name\":\"Farhan Chowdhury\",\"role\":\"Software Engineer\",\"caption\":\"smooth process\"},{\"quote\":\"From hotel bookings to the return ticket, A&A Aviation handled everything for our study-abroad trip. Professional, responsive, and genuinely helpful.\",\"name\":\"Sadia Rahman\",\"role\":\"University Student\",\"caption\":\"highly recommend\"},{\"quote\":\"From hotel bookings to the return ticket, A&A Aviation handled everything for our study-abroad trip. Professional, responsive, and genuinely helpful.\",\"name\":\"Nusrat Jahan\",\"role\":\"Business Owner\",\"caption\":\"great experiences\"}]','2026-08-30 05:38:59.779'),
('home_ticket_cards','[{\"title\":\"Domestic Air Tickets\",\"description\":\"Travel across Bangladesh with affordable fares and flexible flight schedules.\",\"image\":\"/uploads/ticket-cards/ca4cbc1f-6961-4083-9f0b-edbc70cf6b0e.jpg\"},{\"title\":\"International Air Tickets\",\"description\":\"Fly worldwide with trusted airlines and competitive international ticket prices.\",\"image\":\"/uploads/ticket-cards/7e8a9b5b-4426-4ed2-8f04-d7100c276bab.jpg\"},{\"title\":\"One-Way Booking\",\"description\":\"Ideal for business, study, relocation or flexible travel plans.\",\"image\":\"/uploads/ticket-cards/dcbf8297-8c1b-4bc5-a3e2-d83f7a6efaf2.jpg\"},{\"title\":\"Round Trip Booking\",\"description\":\"Book departure and return flights together for convenience and savings.\",\"image\":\"/uploads/ticket-cards/8ec2b2af-53da-4e81-b262-a75f085953e5.jpg\"},{\"title\":\"Group Booking Solutions\",\"description\":\"Affordable fares and flexible flight schedules for teams and families.\",\"image\":\"/uploads/ticket-cards/deb328b7-dfde-4fb6-b029-e6e05a22f47a.jpg\"}]','2026-08-30 01:17:27.190'),
('home_visa_cards','[{\"tag\":\"Portugal Visa-01\",\"title\":\"Work Visa\",\"image\":\"/uploads/visa-cards/274c07dc-72c6-4261-9846-1477bc71ce99.jpg\"},{\"tag\":\"Portugal Visa-02\",\"title\":\"Family Visa\",\"image\":\"/uploads/visa-cards/c5cd9b76-0b0f-4ce0-b110-e1a4f49570a9.jpg\"},{\"tag\":\"Portugal Visa-03\",\"title\":\"Seasonal Visa\",\"image\":\"/uploads/visa-cards/690274e2-89fa-4aa8-a123-e3d10aff21f2.jpg\"},{\"tag\":\"Portugal Visa-04\",\"title\":\"Student Visa\",\"image\":\"/uploads/visa-cards/ae906326-2221-4778-9e20-fe4a2302c552.jpg\"},{\"tag\":\"Portugal Visa-05\",\"title\":\"Tourist Visa\",\"image\":\"/uploads/visa-cards/cf7d226d-a7ce-4f69-a2ae-c36d622c8ea2.jpg\"}]','2026-08-30 04:21:43.431'),
('refund_policy','{\"enabled\":true,\"intro\":\"This Refund Policy explains how cancellations and refunds are handled for air tickets, visa processing, hotel reservations, and other services booked through A&A Aviation.\",\"lastUpdated\":\"11 August 2026\",\"sections\":[{\"title\":\"Airline Tickets\",\"body\":\"Refunds for air tickets follow the fare rules and cancellation policy of the issuing airline, not A&A Aviation. Airline cancellation fees, fare differences, and non-refundable ticket restrictions apply as set by the airline.\"},{\"title\":\"Visa Processing Fees\",\"body\":\"Our service fee for preparing and submitting a visa application is non-refundable once the application has been submitted to the embassy or immigration authority, regardless of the outcome. Embassy or government fees are refunded only if and as the embassy itself allows.\"},{\"title\":\"Hotel Reservations\",\"body\":\"Refunds for hotel bookings depend on the rate type and cancellation policy selected at the time of booking. Non-refundable rates cannot be refunded; flexible rates are refunded according to the hotel\'s stated cancellation window.\"},{\"title\":\"How to Request a Refund\",\"body\":\"Send a refund request to our team with your booking or application reference. We\'ll confirm what\'s refundable with the relevant airline, embassy, or hotel and process any eligible refund to your original payment method.\"},{\"title\":\"Processing Time\",\"body\":\"Eligible refunds are typically processed within 7–21 business days, depending on how quickly the airline, embassy, or hotel releases the funds to us.\"},{\"title\":\"Changes to This Policy\",\"body\":\"We may update this Refund Policy from time to time as our services change. The \\\"Last updated\\\" date below reflects the most recent revision.\"}]}','2026-08-29 07:19:52.456'),
('services_hero','{\"eyebrow\":\"Our Services\",\"title\":\"Services\",\"subtitle\":\"Flights, hotels, visas and document services — everything you need for a hassle-free international journey.\",\"image\":\"/uploads/services-hero/87d71902-ec77-4d06-9f69-37ef570c488b.jpg\",\"titleColor\":\"#f0ac27\",\"shadowColor\":\"#ffffff\"}','2026-08-30 04:19:58.050'),
('social_links','[{\"platform\":\"facebook\",\"label\":\"Facebook\",\"url\":\"https://web.whatsapp.com/\",\"icon\":\"\"},{\"platform\":\"twitter\",\"label\":\"Twitter / X\",\"url\":\"https://web.whatsapp.com/\",\"icon\":\"\"},{\"platform\":\"linkedin\",\"label\":\"LinkedIn\",\"url\":\"https://web.whatsapp.com/\",\"icon\":\"\"}]','2026-08-30 04:53:28.979'),
('terms_conditions','{\"enabled\":true,\"intro\":\"These Terms & Conditions govern your use of the A&A Aviation website and the travel, visa, and related services we provide. By using this site or engaging our services, you agree to the terms below.\",\"lastUpdated\":\"11 August 2026\",\"sections\":[{\"title\":\"Our Services\",\"body\":\"A&A Aviation arranges air ticketing, visa processing, hotel reservations, and document legalization on your behalf. We act as an intermediary between you and airlines, embassies, hotels, and other third-party providers, who set their own rules, fares, and approval decisions.\"},{\"title\":\"Bookings & Payments\",\"body\":\"Fares, visa fees, and service charges are confirmed at the time of booking and may change until full payment is received. Full or partial payment may be required in advance depending on the airline, embassy, or hotel\'s own policy.\"},{\"title\":\"Your Responsibilities\",\"body\":\"You\'re responsible for providing accurate personal details and genuine documents, meeting application deadlines, and checking passport validity, visa, and entry requirements for your destination before travel.\"},{\"title\":\"Visa & Booking Outcomes\",\"body\":\"Visa approval is at the sole discretion of the relevant embassy or immigration authority. We prepare and submit applications carefully, but we cannot guarantee approval, processing times, or that a booking remains available until it\'s confirmed and paid for.\"},{\"title\":\"Limitation of Liability\",\"body\":\"A&A Aviation is not liable for losses caused by airline schedule changes, embassy delays or refusals, incomplete information provided by you, or events beyond our reasonable control.\"},{\"title\":\"Changes to These Terms\",\"body\":\"We may update these Terms & Conditions from time to time as our services change. The \\\"Last updated\\\" date below reflects the most recent revision.\"}]}','2026-08-29 04:46:59.632');
COMMIT;
